export const envelope = [17, 26, 23];

export default function build(api) {
  const woodPlanks = api.theme.wood?.planks ?? "minecraft:oak_planks";
  const woodLog = api.theme.wood?.log ?? "minecraft:oak_log";
  const woodStripped = api.theme.wood?.stripped ?? woodLog;
  const woodStairs = api.theme.wood?.stairs ?? "minecraft:oak_stairs";
  const woodSlab = api.theme.wood?.slab ?? "minecraft:oak_slab";
  const woodFence = api.theme.wood?.fence ?? "minecraft:oak_fence";
  const woodTrapdoor = api.theme.wood?.trapdoor ?? "minecraft:oak_trapdoor";

  function getBase(blockStr) {
    return blockStr.split("[")[0];
  }

  function stair(facing, half = "bottom", shape = "straight") {
    return `${getBase(woodStairs)}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function slab(type = "bottom") {
    return `${getBase(woodSlab)}[type=${type}]`;
  }

  function logAx(axis = "y", stripped = false) {
    const base = getBase(stripped ? woodStripped : woodLog);
    return `${base}[axis=${axis}]`;
  }

  function trapdoor(facing = "north", half = "bottom", open = false) {
    return `${getBase(woodTrapdoor)}[facing=${facing},half=${half},open=${open}]`;
  }

  function fence() {
    return woodFence;
  }

  const setBlock = (x, y, z, block) => {
    if (
      x >= 0 &&
      x < api.size[0] &&
      y >= 0 &&
      y < api.size[1] &&
      z >= 0 &&
      z < api.size[2]
    ) {
      api.set(Math.floor(x), Math.floor(y), Math.floor(z), block);
    }
  };

  function placeGroundSupport(x, z, topY, block) {
    const h = api.heightAt(x, z);
    const minY = Math.min(0, h);
    const maxY = Math.max(topY, h);
    for (let y = minY; y <= maxY; y++) {
      setBlock(x, y, z, block);
    }
  }

  // -------------------------------------------------------------
  // 1. CARRIAGE / SLED RUNNERS & DECK (Y = 0..3)
  // -------------------------------------------------------------

  // Longitudinal runners
  for (let z = 2; z <= 20; z++) {
    for (const x of [4, 5, 11, 12]) {
      placeGroundSupport(x, z, 1, woodLog);
      setBlock(x, 1, z, logAx("z"));
      setBlock(x, 2, z, logAx("z"));
    }
  }

  // Upturned skid ends
  for (const x of [4, 5, 11, 12]) {
    setBlock(x, 2, 2, stair("north", "top"));
    setBlock(x, 2, 20, stair("south", "top"));
  }

  // Heavy crossbeams
  const crossZ = [3, 4, 7, 8, 11, 12, 15, 16, 19, 20];
  for (const cz of crossZ) {
    for (let x = 4; x <= 12; x++) {
      placeGroundSupport(x, cz, 1, woodLog);
      setBlock(x, 2, cz, logAx("x"));
    }
  }

  // Sled platform decking
  for (let z = 3; z <= 19; z++) {
    for (let x = 5; x <= 11; x++) {
      setBlock(x, 2, z, woodPlanks);
    }
  }

  // -------------------------------------------------------------
  // 2. MASSIVE TIMBER DISC WHEELS & AXLES
  // -------------------------------------------------------------

  function buildWheel(cx, cy, cz, dir) {
    const xOuter = cx + dir;

    // Axle hub
    setBlock(cx, cy, cz, logAx("x", true));
    setBlock(
      xOuter,
      cy,
      cz,
      trapdoor(dir < 0 ? "west" : "east", "bottom", false)
    );

    // Cardinal spokes
    setBlock(cx, cy + 1, cz, logAx("y", true));
    setBlock(xOuter, cy + 1, cz, woodPlanks);
    setBlock(cx, cy - 1, cz, logAx("y", true));
    setBlock(xOuter, cy - 1, cz, woodPlanks);

    setBlock(cx, cy, cz - 1, logAx("z", true));
    setBlock(xOuter, cy, cz - 1, woodPlanks);
    setBlock(cx, cy, cz + 1, logAx("z", true));
    setBlock(xOuter, cy, cz + 1, woodPlanks);

    // Rounded wheel rims
    setBlock(cx, cy + 1, cz - 1, stair("south", "top"));
    setBlock(xOuter, cy + 1, cz - 1, stair("south", "top"));

    setBlock(cx, cy + 1, cz + 1, stair("north", "top"));
    setBlock(xOuter, cy + 1, cz + 1, stair("north", "top"));

    setBlock(cx, cy - 1, cz - 1, stair("south", "bottom"));
    setBlock(xOuter, cy - 1, cz - 1, stair("south", "bottom"));

    setBlock(cx, cy - 1, cz + 1, stair("north", "bottom"));
    setBlock(xOuter, cy - 1, cz + 1, stair("north", "bottom"));

    // Ground footing under wheels
    for (let dz = -1; dz <= 1; dz++) {
      placeGroundSupport(cx, cz + dz, 0, woodLog);
      placeGroundSupport(xOuter, cz + dz, 0, woodLog);
    }
  }

  const axlePositions = [5, 11, 17];
  for (const zAxle of axlePositions) {
    for (let x = 2; x <= 14; x++) {
      setBlock(x, 2, zAxle, logAx("x"));
    }
    buildWheel(2, 2, zAxle, -1);
    buildWheel(14, 2, zAxle, 1);
  }

  // Prow hitch and tow ropes extending forward
  for (let z = 0; z <= 2; z++) {
    for (let x = 7; x <= 9; x++) {
      placeGroundSupport(x, z, 1, woodLog);
      setBlock(x, 1, z, logAx("z"));
      setBlock(x, 2, z, woodPlanks);
    }
  }
  setBlock(6, 2, 0, fence());
  setBlock(8, 3, 0, fence());
  setBlock(10, 2, 0, fence());
  setBlock(8, 2, 0, stair("north", "top"));

  // -------------------------------------------------------------
  // 3. FOUR CARPENTERED LEGS (Y = 3..11)
  // -------------------------------------------------------------

  function buildFrontLeg(minX, maxX, isLeft) {
    const innerX = isLeft ? maxX : minX;
    const outerX = isLeft ? minX : maxX;

    // Hoof (Y = 3)
    for (
      let x = outerX;
      x !== innerX + (isLeft ? 1 : -1);
      x += isLeft ? 1 : -1
    ) {
      for (let z = 5; z <= 6; z++) {
        setBlock(x, 3, z, logAx("y"));
      }
    }
    setBlock(outerX, 3, 4, stair("south", "bottom"));

    // Lower leg (Y = 4..6)
    for (let y = 4; y <= 6; y++) {
      for (
        let x = outerX;
        x !== innerX + (isLeft ? 1 : -1);
        x += isLeft ? 1 : -1
      ) {
        for (let z = 5; z <= 6; z++) {
          setBlock(x, y, z, logAx("y", true));
        }
      }
    }

    // Knee joint (Y = 7..8)
    for (let y = 7; y <= 8; y++) {
      for (let x = minX; x <= maxX; x++) {
        for (let z = 5; z <= 6; z++) {
          setBlock(x, y, z, woodPlanks);
        }
        setBlock(x, y, 4, stair("north", y === 7 ? "bottom" : "top"));
      }
    }

    // Upper leg / Shoulder (Y = 9..11)
    for (let y = 9; y <= 11; y++) {
      for (let x = minX; x <= maxX; x++) {
        for (let z = 4; z <= 7; z++) {
          setBlock(x, y, z, woodPlanks);
        }
      }
      setBlock(outerX, y, 4, logAx("y"));
      setBlock(outerX, y, 7, logAx("y"));
    }
  }

  function buildBackLeg(minX, maxX, isLeft) {
    const innerX = isLeft ? maxX : minX;
    const outerX = isLeft ? minX : maxX;

    // Hoof (Y = 3)
    for (
      let x = outerX;
      x !== innerX + (isLeft ? 1 : -1);
      x += isLeft ? 1 : -1
    ) {
      for (let z = 15; z <= 16; z++) {
        setBlock(x, 3, z, logAx("y"));
      }
    }
    setBlock(outerX, 3, 14, stair("south", "bottom"));

    // Lower leg (Y = 4..5)
    for (let y = 4; y <= 5; y++) {
      for (
        let x = outerX;
        x !== innerX + (isLeft ? 1 : -1);
        x += isLeft ? 1 : -1
      ) {
        for (let z = 15; z <= 16; z++) {
          setBlock(x, y, z, logAx("y", true));
        }
      }
    }

    // Hock joint (Y = 6..7, angled backward)
    for (let y = 6; y <= 7; y++) {
      for (let x = minX; x <= maxX; x++) {
        for (let z = 15; z <= 17; z++) {
          setBlock(x, y, z, woodPlanks);
        }
        setBlock(x, y, 18, stair("north", y === 6 ? "bottom" : "top"));
      }
    }

    // Thigh / Gaskin (Y = 8..11)
    for (let y = 8; y <= 11; y++) {
      for (let x = minX; x <= maxX; x++) {
        for (let z = 14; z <= 17; z++) {
          setBlock(x, y, z, woodPlanks);
        }
      }
      setBlock(outerX, y, 14, logAx("y"));
      setBlock(outerX, y, 17, logAx("y"));
    }
  }

  buildFrontLeg(4, 6, true);
  buildFrontLeg(10, 12, false);
  buildBackLeg(4, 6, true);
  buildBackLeg(10, 12, false);

  // Underbelly structural tie beams
  for (let x = 6; x <= 10; x++) {
    setBlock(x, 9, 6, logAx("x"));
    setBlock(x, 9, 15, logAx("x"));
  }

  // -------------------------------------------------------------
  // 4. TORSO HULL & HOLLOW INTERIOR (Y = 10..18, Z = 4..18)
  // -------------------------------------------------------------

  for (let z = 4; z <= 18; z++) {
    let centerY = 14.0;
    let rx = 4.3;
    let ry = 3.9;

    if (z <= 6) {
      centerY = 14.5;
      rx = 3.2 + (z - 4) * 0.5;
      ry = 3.2 + (z - 4) * 0.35;
    } else if (z >= 16) {
      centerY = 14.5;
      rx = 4.3 - (z - 15) * 0.35;
      ry = 3.9 - (z - 15) * 0.25;
    }

    const isRib = z % 2 === 0;

    for (let y = 10; y <= 18; y++) {
      for (let x = 3; x <= 13; x++) {
        const dx = (x - 8) / rx;
        const dy = (y - centerY) / ry;
        const d2 = dx * dx + dy * dy;

        if (d2 <= 1.05) {
          // Hollow interior cavity: left strictly empty for compiler fit-out
          if (x >= 6 && x <= 10 && y >= 11 && y <= 16 && z >= 7 && z <= 15) {
            continue;
          }

          // Interior floor plane (Y = 10)
          if (y === 10 && z >= 7 && z <= 15 && x >= 6 && x <= 10) {
            if (x >= 7 && x <= 9 && z >= 10 && z <= 12) {
              // Secret trapdoor hatch on the belly
              setBlock(x, 10, z, trapdoor("north", "top", false));
            } else {
              setBlock(x, 10, z, woodPlanks);
            }
            continue;
          }

          // Interior ceiling plane (Y = 17)
          if (y === 17 && z >= 7 && z <= 15 && x >= 6 && x <= 10) {
            setBlock(x, 17, z, isRib ? logAx("x") : woodPlanks);
            continue;
          }

          // Outer timber hull and ribs
          if (d2 >= 0.65 || z < 7 || z > 15) {
            if (isRib && (Math.abs(dx) > 0.58 || Math.abs(dy) > 0.58)) {
              setBlock(x, y, z, logAx("y"));
            } else {
              setBlock(x, y, z, woodPlanks);
            }
          } else {
            setBlock(x, y, z, woodPlanks);
          }
        }
      }
    }
  }

  // Dorsal spine smoothing along top of barrel
  for (let z = 6; z <= 17; z++) {
    setBlock(8, 18, z, slab("bottom"));
    setBlock(7, 18, z, stair("east", "bottom"));
    setBlock(9, 18, z, stair("west", "bottom"));
  }

  // Secret spy slits along the flanks
  for (const z of [9, 11, 13]) {
    setBlock(4, 13, z, stair("south", "top"));
    setBlock(12, 13, z, stair("south", "top"));
  }

  // Secret deployment ropes hanging beneath the belly hatch
  setBlock(8, 9, 11, fence());
  setBlock(8, 8, 11, fence());

  // -------------------------------------------------------------
  // 5. ARCHED NECK & CARVED MANE (Y = 16..24, Z = 3..8)
  // -------------------------------------------------------------

  const neckLevels = [
    { y: 16, zMin: 4, zMax: 7, xMin: 6, xMax: 10 },
    { y: 17, zMin: 4, zMax: 7, xMin: 6, xMax: 10 },
    { y: 18, zMin: 4, zMax: 7, xMin: 6, xMax: 10 },
    { y: 19, zMin: 3, zMax: 6, xMin: 6, xMax: 10 },
    { y: 20, zMin: 3, zMax: 6, xMin: 7, xMax: 9 },
    { y: 21, zMin: 3, zMax: 5, xMin: 7, xMax: 9 },
    { y: 22, zMin: 3, zMax: 5, xMin: 7, xMax: 9 },
    { y: 23, zMin: 3, zMax: 5, xMin: 7, xMax: 9 }
  ];

  for (const lvl of neckLevels) {
    for (let z = lvl.zMin; z <= lvl.zMax; z++) {
      for (let x = lvl.xMin; x <= lvl.xMax; x++) {
        if (x === 8) {
          setBlock(x, lvl.y, z, logAx("y", true));
        } else {
          setBlock(x, lvl.y, z, woodPlanks);
        }
      }
    }
  }

  // Throat contour
  for (let y = 19; y <= 22; y++) {
    setBlock(8, y, 2, stair("north", "top"));
    setBlock(7, y, 3, stair("north", "bottom"));
    setBlock(9, y, 3, stair("north", "bottom"));
  }

  // Homeric crested mane running down the spine
  setBlock(8, 25, 5, slab("bottom"));
  setBlock(8, 24, 6, stair("south", "bottom"));
  setBlock(8, 23, 6, logAx("z", true));
  setBlock(8, 22, 6, stair("south", "top"));
  setBlock(8, 22, 7, stair("south", "bottom"));
  setBlock(8, 21, 7, logAx("z", true));
  setBlock(8, 20, 7, stair("south", "top"));
  setBlock(8, 20, 8, stair("south", "bottom"));
  setBlock(8, 19, 8, logAx("z", true));
  setBlock(8, 18, 8, slab("top"));

  const maneTufts = [
    [24, 6],
    [22, 7],
    [20, 8]
  ];
  for (const [my, mz] of maneTufts) {
    setBlock(7, my, mz, stair("east", "bottom"));
    setBlock(9, my, mz, stair("west", "bottom"));
  }

  // -------------------------------------------------------------
  // 6. HEAD, MUZZLE, EARS & HARNESS (Y = 20..25, Z = 1..5)
  // -------------------------------------------------------------

  // Lower jaw (Y = 20)
  for (let x = 7; x <= 9; x++) {
    setBlock(x, 20, 1, stair("north", "top"));
    setBlock(x, 20, 2, woodPlanks);
  }
  setBlock(8, 19, 2, slab("top"));

  // Muzzle & Mouth (Y = 21)
  for (let x = 7; x <= 9; x++) {
    setBlock(x, 21, 1, woodPlanks);
    setBlock(x, 21, 2, woodPlanks);
    setBlock(x, 21, 3, woodPlanks);
  }
  setBlock(7, 21, 1, stair("north", "bottom"));
  setBlock(9, 21, 1, stair("north", "bottom"));
  setBlock(8, 21, 1, logAx("z", true));

  // Bridge of Nose & Cheeks (Y = 22)
  for (let x = 7; x <= 9; x++) {
    setBlock(x, 22, 2, stair("north", "bottom"));
    setBlock(x, 22, 3, woodPlanks);
    setBlock(x, 22, 4, woodPlanks);
  }
  setBlock(6, 22, 3, stair("west", "bottom"));
  setBlock(6, 22, 4, stair("west", "bottom"));
  setBlock(10, 22, 3, stair("east", "bottom"));
  setBlock(10, 22, 4, stair("east", "bottom"));

  // Eyes & Brow (Y = 23)
  for (let x = 7; x <= 9; x++) {
    setBlock(x, 23, 3, stair("north", "bottom"));
    setBlock(x, 23, 4, woodPlanks);
    setBlock(x, 23, 5, woodPlanks);
  }
  setBlock(6, 23, 4, stair("south", "bottom"));
  setBlock(10, 23, 4, stair("south", "bottom"));

  // Crown & Forelock (Y = 24)
  for (let x = 7; x <= 9; x++) {
    setBlock(x, 24, 4, woodPlanks);
    setBlock(x, 24, 5, woodPlanks);
  }
  setBlock(8, 24, 3, stair("north", "bottom"));

  // Alert Ears (Y = 24..25)
  setBlock(6, 24, 5, logAx("y", true));
  setBlock(6, 25, 5, stair("north", "bottom"));
  setBlock(6, 25, 4, stair("south", "top"));

  setBlock(10, 24, 5, logAx("y", true));
  setBlock(10, 25, 5, stair("north", "bottom"));
  setBlock(10, 25, 4, stair("south", "top"));

  // Bridle bit & reins
  setBlock(6, 21, 2, fence());
  setBlock(10, 21, 2, fence());
  setBlock(6, 22, 2, fence());
  setBlock(10, 22, 2, fence());

  setBlock(5, 20, 3, fence());
  setBlock(11, 20, 3, fence());
  setBlock(5, 19, 4, fence());
  setBlock(11, 19, 4, fence());
  setBlock(5, 18, 5, fence());
  setBlock(11, 18, 5, fence());
  setBlock(5, 17, 6, fence());
  setBlock(11, 17, 6, fence());

  // -------------------------------------------------------------
  // 7. RUMP & FLOWING WOODEN TAIL (Y = 7..17, Z = 18..21)
  // -------------------------------------------------------------

  setBlock(8, 17, 18, logAx("z", true));
  setBlock(8, 16, 19, logAx("y", true));
  setBlock(7, 16, 19, stair("east", "bottom"));
  setBlock(9, 16, 19, stair("west", "bottom"));

  setBlock(8, 15, 19, logAx("y", true));
  setBlock(8, 15, 20, stair("north", "top"));
  setBlock(7, 15, 19, stair("east", "bottom"));
  setBlock(9, 15, 19, stair("west", "bottom"));

  setBlock(8, 14, 20, logAx("y", true));
  setBlock(7, 14, 20, stair("east", "bottom"));
  setBlock(9, 14, 20, stair("west", "bottom"));

  setBlock(8, 13, 20, logAx("y", true));
  setBlock(7, 13, 20, woodPlanks);
  setBlock(9, 13, 20, woodPlanks);

  setBlock(8, 12, 20, logAx("y", true));
  setBlock(7, 12, 20, fence());
  setBlock(9, 12, 20, fence());

  setBlock(8, 11, 20, logAx("y", true));
  setBlock(8, 11, 21, slab("bottom"));

  setBlock(8, 10, 20, logAx("y", true));
  setBlock(8, 9, 20, stair("south", "bottom"));
  setBlock(8, 8, 20, fence());
  setBlock(8, 7, 20, fence());

  return {
    name: "The Trojan Horse",
    seatY: 0,
    anchors: {
      front: [8, 2, 0],
      trapdoor: [8, 10, 11],
      head: [8, 23, 2]
    },
    interiors: [
      {
        min: [6, 11, 7],
        max: [10, 16, 15],
        kind: "quarters"
      }
    ]
  };
}
